def second_largest(nums):
    distinct = []
    for value in nums:
        if value not in distinct:
            distinct.append(value)

    if len(distinct) < 2:
        raise ValueError("Not enough distinct values to determine the second largest")

    largest = max(distinct)
    second = None
    for value in distinct:
        if value != largest:
            if second is None or value > second:
                second = value
    return second
```
